Rules.InvariantScript:
UpdateContext({locLoading: false});
// Get Fabric Table Data
// keep <= your app data row limit
Clear(colAssumptionsGermanyTaxSQL);
Clear(colAssumptionsFranceSQL);
// 1. Calculate the max rows outside the loop and store them
UpdateContext(
    {
        locLastRowGermany: First(
            SortByColumns(
                'Assumptions Local Tax Germanies',
                "vsb_row_num",
                SortOrder.Descending
            )
        ).vsb_row_num,
        // Ensure you use the exact logical name here
        locLastRowFrance: First(
            SortByColumns(
                'Assumptions Local Tax Frances',
                "vsb_row_num",// Assuming France has the exact same schema
                SortOrder.Descending
            )
        ).vsb_row_num,
        locBatchSize: 2000
    }
);
UpdateContext(
    {
        locAbsoluteMax: Max(
            locLastRowGermany,
            locLastRowFrance
        )
    }
);
// 2. Run the batched collection
ForAll(
    Sequence(
        RoundUp(
            locAbsoluteMax / locBatchSize,
            0
        )
    ) As Batch,
    With(
        {
            // Pre-calculate the exact math boundaries here to avoid breaking delegation in the Filter
            locStartPoint: (Batch.Value - 1) * locBatchSize,
            locEndPoint: Batch.Value * locBatchSize
        },
        Concurrent(
        // Germany Collection
            If(
                locLastRowGermany >= locStartPoint,
                Collect(
                    colAssumptionsGermanyTaxSQL,
                    Filter(
                        'Assumptions Local Tax Germanies',
                        vsb_row_num > locStartPoint And vsb_row_num <= locEndPoint
                    )
                )
            ),
        // France Collection
            If(
                locLastRowFrance >= locStartPoint,
                Collect(
                    colAssumptionsFranceSQL,
                    Filter(
                        'Assumptions Local Tax Frances',
                        vsb_row_num > locStartPoint And vsb_row_num <= locEndPoint
                    )
                )
            )
        )
    )
);
UpdateContext({locLoading: true});

